import styled from '@emotion/styled';

type CheckInputState = 'none' | 'selected';

interface StyledCheckInputProps {
  $checked?: CheckInputState;
  $isDisabled?: boolean;
  $error?: boolean;
}

export const StyledCheckInput = styled.div<StyledCheckInputProps>(
  ({ $checked = 'none', $isDisabled, $error }) => ({
    height: '20px',
    width: '20px',
    minHeight: '20px',
    minWidth: '20px',
    maxHeight: '20px',
    maxWidth: '20px',
    flexShrink: 0,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    border: '1px solid #b8b8b8',
    borderRadius: '4px',
    marginLeft: 'auto',
    boxSizing: 'border-box',

    '&:hover:not([data-disabled="true"])': {
      border: '2px solid #E5B611',
    },

    ...($checked === 'none' && {
      backgroundColor: 'transparent',
      borderColor: '#b8b8b8',
    }),
    ...($checked === 'selected' && {
      backgroundColor: '#E5B611',
      borderColor: '#E5B611',
    }),
    ...($isDisabled && {
      opacity: 0.5,
      backgroundColor: '#f5f5f5',
      borderColor: '#e0e0e0',

      '&:hover': {
        borderColor: '#e0e0e0',
      },
    }),
    ...($error && {
      borderColor: '#D62222',

      '&:hover': {
        borderColor: '#D62222',
      },
    }),
    ...($checked === 'selected' &&
      $isDisabled && {
        backgroundColor: '#c0c0c0',
        borderColor: '#e1e1e1',
      }),
  }),
);

interface StyledCustomOptionProps {
  $isDisabled?: boolean;
}

export const StyledCustomOption = styled.div<StyledCustomOptionProps>(
  ({ $isDisabled }) => ({
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
    height: '100%',
    ...($isDisabled && {
      opacity: 0.5,
      cursor: 'not-allowed',
      pointerEvents: 'none',
    }),
    [`&:hover ${StyledCheckInput}:not([data-disabled="true"])`]: {
      border: '2px solid #E5B611',
    },
  }),
);
